/// <summary>
///
/// </summary>
public void insert()
{
    TFMPageMenuItems relatedline;

    select forupdate firstonly relatedline order by LineNumber desc where relatedline.PageID == this.PageID;
    this.LineNumber = relatedline.LineNumber + 1;
    super();

}

/// <summary>
/// Find the menu items for the page and the page and the menu item id.
/// </summary>
public static TFMPageMenuItems find(str _pageId, str _menuItemId)
{
    TFMPageMenuItems line;
    select forupdate firstonly line where line.PageID == _pageId && line.MenuPageID == _menuItemId;
    return line;
}

/// <summary>
/// Deletes the menu items for the page
/// </summary>
/// <param name = "_pageId">The id of the page to delete</param>
public static void deleteMenuItemsForPage(TFMPageID _pageId)
{
    TFMPageMenuItems mobPageMenuItems;
    ttsbegin;
    delete_from mobPageMenuItems where mobPageMenuItems.PageID == _pageId;
    ttscommit;
}

/// <summary>
///
/// </summary>
public static void createStandardOverride(TFMPageID _pageId)
{
    TFMPageMenuItems    existingline;
    TFMPageMenuItems	menuItemsTable;
    TFMPage				page;
    TFMPages			pages;
    Map					actions;
    MapEnumerator		mEnum;
    TFMMenuItemStateConfiguration menuItem;

    pages = TFMPagesProvider::getAllPages();
    page = pages.getPage(_pageId);
    if (page)
    {
        actions = page.getPageActions();
        mEnum = actions.getEnumerator();
        while (mEnum.moveNext())
        {
            menuItem = mEnum.currentValue();

            select forupdate firstonly existingline where existingline.PageID == _pageId && existingline.MenuPageID == menuItem.parmMenuItemName();
            if(!existingline)
            {
                menuItemsTable.PageID       = page.parmId();
                menuItemsTable.MenuPageID   = menuItem.parmMenuItemName();
                menuItemsTable.Enabled		= menuItem.parmEnabled();
                menuItemsTable.PromotedItem		= menuItem.parmPromoted() > -1;
                menuItemsTable.insert();
            }
        }
    }
}

    /// <summary>
    /// Creates non existing menu items.
    /// </summary>
    /// <param name = "_sortedMenuItems">The menu items that should be added in a sorted map</param>
    /// <param name = "_page">The page to add the menu items to</param>
    public static void createMenuItems(Map _sortedMenuItems, TFMPage _page)
    {
        TFMPageMenuItems				existingline;
        TFMPageMenuItems				menuItemsTable;
        MapEnumerator					sortedMenuItemsEnum;
        TFMPageActionAttribute			pageActionType;
        TFMPageID						pageId;
        TFMMenuItemStateConfiguration	menuItem;
        MapEnumerator					mEnum;

        if(!_page)
        {
            return;
        }
        pageId = _page.parmId();

        sortedMenuItemsEnum = _sortedMenuItems.getEnumerator();

        ttsbegin;
        while (sortedMenuItemsEnum.moveNext())
        {
            menuItem = sortedMenuItemsEnum.currentValue();

            select forupdate firstonly existingline where existingline.PageID == pageId && existingline.MenuPageID == menuItem.parmMenuItemName();
            if(!existingline)
            {
                menuItemsTable.PageID       = pageId;
                menuItemsTable.MenuPageID   = menuItem.parmMenuItemName();
                menuItemsTable.Enabled		= menuItem.parmEnabled();

                pageActionType              = menuItem.getPageActionSetup();
                if(pageActionType)
                {
                    menuItemsTable.Hide              = pageActionType.parmHide();
                    menuItemsTable.PromotedItem	     = pageActionType.parmPromoted();
                    menuItemsTable.Icon              = pageActionType.parmIcon();
                    menuItemsTable.MenuItemType      = pageActionType.parmMenuItemType();
                    menuItemsTable.Mandatory         = pageActionType.parmMandatory();
                    menuItemsTable.Title		     = (pageActionType.parmMenuItemType() == TFMPageMenuItemTypes::AdhocAction || menuItem.titleChanged()) ? menuItem.parmTitle() : ''; //Adhoc action has no page to inherit from
                    menuItemsTable.VisibleWhenNoData = _page.getListId() != '' ? pageActionType.parmVisibleWhenNoData() : true;
                } 
                else
                {
                    menuItemsTable.PromotedItem = menuItem.parmPromoted() > -1;
                }

                menuItemsTable.insert(); // the insert method handles the lineNumber
				if (menuItem.parmAdditionalProperties())
                {
                    mEnum = menuItem.parmAdditionalProperties().getparameters().getEnumerator();
					while(mEnum.moveNext())
                    {
                        TFMPageConfigParms::CreateOrUpdateParameter(pageId , classId2Name(classIdGet(_page.getConfiguration())), menuItem.parmMenuItemName() + mEnum.currentKey(), conPeek(mEnum.currentValue(),1));
                    }
                }
            }
        }
        ttscommit;
    }

/// <summary>
/// Gets the mandatory menu items for the page.
/// </summary>
/// <param name = "_page">The page to get the mandatory menu items for.</param>
/// <returns>A map of the xpath of the parm method as key and a TFMMenuItemStateConfiguration as value</returns>
public static Map getMandatoryMenuItems(TFMPage _page)
{
    TFMPageConfigurationAttributeAttribute  configAttr;
    SysDictMethod		                    DM;
    TFMPageActionAttribute                  pageActionType;
    TFMPage                                 page      = _page;
    TFMMenuItemStateConfiguration           menuItem;
    SetEnumerator                           methodSet;
    Map					                    menuItems = new Map(Types::String, Types::Class);

    if(!page)
    {
        return menuItems;
    }

    methodSet = TFMFormLookupHelper::parmMethodsOnClass(classIdGet(page.getConfiguration())).getEnumerator();
    while (methodSet.moveNext())
    {
        DM = new SysDictMethod(UtilElementType::ClassInstanceMethod,classIdGet(page.getConfiguration()), methodSet.current());
        configAttr = DM.getAttribute(classStr(TFMPageConfigurationAttributeAttribute));

        if(configAttr)
        {
            pageActionType = TFMFormLookupHelper::IsDefinedAsPageActionAttribute(configAttr.parmXPath(), page.getConfiguration());
            if(pageActionType)
            {
                menuItem = TFMMenuItemStateConfiguration::Construct(configAttr.parmXPath(), -1, pageActionType);
                menuItem.parmEnabled(true);
                pageActionType.parmMandatory(true); // the menu item will be mandatory because it is a page defined menu item.
                pageActionType.parmVisibleWhenNoData(configAttr.parmVisibleWhenNoData());
                menuItem.parmIcon(pageActionType.parmIcon());

                if(DM.returnId() ==  extendedTypeNum(TFMPageTitleString))
                {
                    menuItem.parmTitle(configAttr.parmDefaultValue());
                }

                menuItem.parmPromoted(pageActionType.parmPromoted() ? 1 : -1);
                menuItems.add(configAttr.parmXPath(), menuItem);
            }
        }
    }
    return menuItems;
}

/// <summary>
/// Making sure that all menu items has a line number taking the Promoted column into account.
/// </summary>
public static void convertPromotedAndAddLineNumbers()
{
    TFMPageMenuItems	countLine;
    TFMPageMenuItems	menuItemsTable;
    ttsbegin;
    while select forupdate menuItemsTable order by menuItemsTable.Promoted where menuItemsTable.LineNumber < 1.0
    {
        select forupdate firstonly countLine order by LineNumber desc where countLine.PageId == menuItemsTable.PageId;
        if(countLine)
        {
            menuItemsTable.LineNumber = countLine.LineNumber + 1;
        } else
        {
            menuItemsTable.LineNumber = 1;
        }
        menuItemsTable.update();
    }
    ttscommit;
}

/// <summary>
///
/// </summary>
public void switchMenuItemPlacement(RecId _toItemRecId)
{
    TFMPageMenuItems relatedline;
    ttsbegin;
    select forupdate firstonly relatedline where relatedline.RecId == _toItemRecId;
    if (!relatedline)
    {
        ttsabort;
        return;
    }
    relatedline.LineNumber = this.LineNumber;
    this.selectForUpdate();
    this.LineNumber = relatedline.orig().LineNumber;
    relatedline.doUpdate();
    this.doUpdate();
    ttscommit;
}
